OPERATIONS = (
    ("LAYER_NORM", "layer_norm", 1024, 1, 1),
    ("RMS_NORM", "rms_norm", 1024, 1, 1),
    ("SUM_SQUARE", "sum_square", 1024, 1, 1),
    ("SOFTMAX", "softmax", 1024, 1, 1),
    ("RVQ_SELECT", "rvq_select", 1024, 1, 1),
    ("FRAME", "frame", 960, 1, 1),
    ("MAGNITUDE", "magnitude", 481, 1, 1),
    ("LOG", "log", 128, 1, 1),
    ("IM2COL_384", "im2col", 384, 3, 1),
    ("IM2COL_3072", "im2col", 3072, 3, 2),
    ("IM2COL_2048", "im2col", 2048, 2, 2),
    ("BIAS", "bias", 1024, 1, 1),
    ("BIAS4096", "bias", 4096, 1, 1),
    ("GELU1024", "gelu", 1024, 1, 1),
    ("GELU", "gelu", 16384, 1, 1),
    ("BIAS_GELU1024", "bias_gelu", 1024, 1, 1),
    ("BIAS_GELU", "bias_gelu", 4096, 1, 1),
    ("SILU_PRODUCT", "silu_product", 4096, 1, 1),
    ("ADD", "add", 1024, 1, 1),
    ("ROPE_PACK", "rope_pack", 1024, 1, 1),
    ("PACK_HEADS", "pack_heads", 1024, 1, 1),
    ("UNPACK_HEADS", "unpack_heads", 1024, 1, 1),
    ("SPEECH_ADD", "speech_add", 1024, 1, 1),
)


def check_wrapper(header, symbol):
    signature = re.search(r"static inline int32_t cute_dsl_" + symbol + r"_wrapper\(([^)]*)\)", header)
    expected = [symbol + "_Kernel_Module_t *module"]
    expected += ["void *" + name for name in ("x", "weight", "bias", "out", "aux", "codes")]
    expected += ["int32_t rows", "int32_t length", "int32_t offset", "float parameter", "cudaStream_t stream"]
    if signature is None or re.sub(r"\s+", "", signature[1]) != re.sub(r"\s+", "", ",".join(expected)):
        raise ValueError("unexpected generated audio support ABI")


def write_dispatcher(destination):
    header = ["#pragma once", "#include <stdint.h>", "enum {"]
    header += [f" AUDIO_{name}={index}," for index, (name, *_) in enumerate(OPERATIONS)]
    header += ["};", 'extern "C" int cuteafd_audio_support_create(void**);',
        'extern "C" int cuteafd_audio_support_destroy(void*);',
        'extern "C" int cuteafd_audio_support_launch(void*,int,int,void*,void*,void*,void*,void*,void*,int,int,int,float,void*);']
    (destination / "cuteafd_audio_support_internal.h").write_text("\n".join(header) + "\n")
    code = ['#include "cuteafd_audio_support_internal.h"', '#include <cuda_runtime.h>', '#include <new>']
    for _, op, width, kernel, stride in OPERATIONS:
        code.append(f'#include "audio_{op}_{width}_{kernel}_{stride}.h"')
    code.append("struct Owner { int device;")
    for name, op, width, kernel, stride in OPERATIONS:
        code.append(f"cuteafd_audio_{op}_{width}_{kernel}_{stride}_Kernel_Module_t {name}{{}};")
    code += ["};", 'extern "C" int cuteafd_audio_support_destroy(void* opaque) {',
        "if(!opaque)return 0;auto* o=static_cast<Owner*>(opaque);int first=0;"]
    for name, *_ in OPERATIONS:
        code.append(f"if(o->{name}.module){{int e=cudaLibraryUnload(o->{name}.module);if(!first)first=e;}}")
    code += ["delete o;return first;}", 'extern "C" int cuteafd_audio_support_create(void** out) {',
        "if(!out)return cudaErrorInvalidValue;*out=nullptr;auto* o=new(std::nothrow)Owner{};",
        "if(!o)return cudaErrorMemoryAllocation;int e=cudaGetDevice(&o->device);"]
    for name, op, width, kernel, stride in OPERATIONS:
        symbol = f"cuteafd_audio_{op}_{width}_{kernel}_{stride}"
        code.append(f"if(!e){{auto* lib=&o->{name}.module;void* args[]={{&lib,&e}};_mlir_{symbol}_cuda_init(args);"
            f"if(!e){{void* load[]={{&lib,&o->device,&e}};_mlir_{symbol}_cuda_load_to_device(load);}}}}")
    code += ["if(e){cuteafd_audio_support_destroy(o);return e;}*out=o;return 0;}",
        'extern "C" int cuteafd_audio_support_launch(void* opaque,int operation,int width,',
        "void* x,void* weight,void* bias,void* out,void* aux,void* codes,",
        "int rows,int length,int offset,float parameter,void* stream) {",
        "if(!opaque || rows<0 || length<=0)return cudaErrorInvalidValue;auto* o=static_cast<Owner*>(opaque);",
        "int device=-1;int e=cudaGetDevice(&device);if(e)return e;if(device!=o->device)return cudaErrorInvalidDevice;",
        "switch(operation){"]
    for name, op, width, kernel, stride in OPERATIONS:
        if name in {"BIAS4096", "GELU1024", "BIAS_GELU1024"}:
            continue
        variants = [row for row in OPERATIONS if row[1] == op]
        # im2col has distinct operation IDs because stride is static geometry.
        if op not in {"bias", "gelu", "bias_gelu"}:
            variants = [(name, op, width, kernel, stride)]
        code.append(f"case AUDIO_{name}:")
        for variant, _, w, k, s in variants:
            code.append(f"if(width=={w})return cute_dsl_cuteafd_audio_{op}_{w}_{k}_{s}_wrapper("
                f"&o->{variant},x,weight,bias,out,aux,codes,rows,length,offset,parameter,static_cast<cudaStream_t>(stream));")
        code.append("break;")
    code.append("}return cudaErrorInvalidValue;}")
    (destination / "audio_support.cc").write_text("\n".join(code) + "\n")


def capture_rotary(snapshot, destination):
    """One-time build-input capture; never part of offline export or serving."""
    import torch
    import torch.nn as nn
    root = Path(__file__).resolve().parents[3]
    ref_path = root / "python/reference/families/mimo_v2/mimo_v26/audio_reference.py"
    spec = importlib.util.spec_from_file_location("audio_reference", ref_path)
    ref = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(ref)
    if torch.__version__ != "2.12.0a0+5aff3928d8.nv26.05" or torch.version.cuda != "13.2":
        raise ValueError("official rotary capture requires pinned NGC 26.05")
    source = ref.checked_source(snapshot / "modeling_mimo_v2.py", ref.MODEL_SHA256)
    qwen_source = root / "third_party/transformers/src/transformers/models/qwen2/modeling_qwen2.py"
    qwen_sha = "34390fea7648b444d5727abef0b85acceba28f856aedec6c335d51253806bfee"
    ref.checked_source(qwen_source, qwen_sha)
    ns = ref.definitions(source, ["AudioTokenizerRotaryEmbedding"], {"torch": torch, "nn": nn}, "official snapshot")
    from transformers.models.qwen2.configuration_qwen2 import Qwen2Config
    from transformers.models.qwen2.modeling_qwen2 import Qwen2RotaryEmbedding
    cfg = json.loads((snapshot / "audio_tokenizer/config.json").read_text())
    audio_cfg = json.loads((snapshot / "config.json").read_text())["audio_config"]
    codec = ns["AudioTokenizerRotaryEmbedding"](
        cfg["rope_theta"], cfg["d_model"] // cfg["encoder_attention_heads"], 3000, cfg["rope_type"])
    patch_cfg = Qwen2Config(hidden_size=audio_cfg["input_local_dim"],
        num_hidden_layers=audio_cfg["input_local_layers"], num_attention_heads=audio_cfg["input_local_attn_heads"],
        num_key_value_heads=audio_cfg["input_local_attn_heads"], intermediate_size=audio_cfg["input_local_intermediate_size"],
        attention_dropout=audio_cfg["input_local_hidden_dropout"], rope_theta=audio_cfg["rope_theta"],
        partial_rotary_factor=audio_cfg["partial_rotary_factor"])
    patch = Qwen2RotaryEmbedding(patch_cfg)
    codec.cuda(); patch.cuda()
    torch.use_deterministic_algorithms(True)
    torch.backends.cuda.matmul.allow_tf32 = False
    with torch.inference_mode():
        cc, cs = codec(torch.zeros(1, device="cuda"), torch.arange(3000, device="cuda"))
        pc, ps = patch(torch.zeros(1, device="cuda"), torch.arange(4, device="cuda")[None])
    tables = {"codec_rotary": torch.cat((cc[:, :32], cs[:, :32]), -1),
              "patch_rotary": torch.cat((pc[0, :, :32], ps[0, :, :32]), -1)}
    captures = {}
    for name, tensor in tables.items():
        raw = tensor.cpu().contiguous().numpy().tobytes()
        captures[name] = {"sha256": hashlib.sha256(raw).hexdigest(), "shape": list(tensor.shape),
                          "zlib_base85": base64.b85encode(zlib.compress(raw, 9)).decode("ascii")}
    destination.mkdir(parents=True, exist_ok=True)
    (destination / "official_rotary_capture.json").write_text(json.dumps({
        "captures": captures, "model_sha256": ref.MODEL_SHA256, "qwen_source_sha256": qwen_sha,
        "transformers_commit": ref.TRANSFORMERS_COMMIT, "torch": torch.__version__,
        "torch_commit": torch.version.git_version, "cuda": torch.version.cuda,
        "device_capability": list(torch.cuda.get_device_capability()),
        "snapshot": snapshot.name}, indent=2) + "\n")


def captured_rotary():
    import torch
    import numpy as np
    tables = {}
    for name, count in (("codec_rotary", 3000 * 64), ("patch_rotary", 4 * 64)):
        record = ROTARY_CAPTURES[name]
        # Exact captured bytes, not a host-libm baseline: ARM and x86 builds
        # reconstruct identical tables without CUDA or platform-dependent trig.
        raw = zlib.decompress(base64.b85decode(record["zlib_base85"]))
        if len(raw) != count * 4 or hashlib.sha256(raw).hexdigest() != record["sha256"]:
            raise ValueError(f"captured {name}: byte pin mismatch")
        tables[name] = torch.from_numpy(np.frombuffer(raw, dtype="<f4").copy()).reshape(-1, 64)
    return tables


def write_tables(destination):
    """Build-time constants match the pinned torchaudio HTK/no-norm formulas.

    Keeping them in the attested native export removes serving-time Python and
    platform-dependent table construction. GPU qualification checks their use.
    """
    import math
    import torch
    hann = torch.hann_window(960, periodic=True, dtype=torch.float32)
    frequencies = torch.linspace(0, 12000, 481, dtype=torch.float32)
    mel_max = 2595.0 * math.log10(1.0 + 12000.0 / 700.0)
    mel_points = torch.linspace(0.0, mel_max, 130, dtype=torch.float32)
    edges = 700.0 * (10.0 ** (mel_points / 2595.0) - 1.0)
    differences = edges[1:] - edges[:-1]
    slopes = edges.unsqueeze(0) - frequencies.unsqueeze(1)
    filterbank = torch.maximum(torch.zeros(1), torch.minimum(
        -slopes[:, :-2] / differences[:-1], slopes[:, 2:] / differences[1:]))
    tensors = {"hann": hann, "filterbank": filterbank, **captured_rotary()}
    lines = ["#pragma once", "// Pinned official geometry; generated offline, no serving-time Python."]
    for name, tensor in tensors.items():
        values = tensor.reshape(-1).tolist()
        lines.append(f"static const float cuteafd_audio_{name}[{len(values)}] = {{")
        for start in range(0, len(values), 8):
            lines.append(",".join(float(value).hex() + "f" for value in values[start:start+8]) + ",")
        lines.append("};")
    (destination / "audio_tables.h").write_text("\n".join(lines) + "\n")
    return {name: hashlib.sha256(tensor.contiguous().numpy().tobytes()).hexdigest()
            for name, tensor in tensors.items()}


def write_identity(destination, manifest):
    """Embed the manifest digest, without circularly hashing its own header."""
    canonical = json.dumps(manifest, sort_keys=True, separators=(",", ":")).encode()
    identity = hashlib.sha256(canonical).hexdigest()
    (destination / "audio_identity.h").write_text(
        '#pragma once\n#define CUTEAFD_AUDIO_EXPORT_SHA256 "' + identity + '"\n')
    return identity


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--capability", type=int, choices=(120, 121))
    parser.add_argument("--capture-official-rotary", type=Path,
                        help="one-time official GPU table capture from this pinned snapshot")
    args = parser.parse_args()
    if args.capture_official_rotary:
        capture_rotary(args.capture_official_rotary, args.output_dir)
        return
    if args.capability is None:
        parser.error("--capability is required for offline AOT export")
    os.environ["CUDA_VISIBLE_DEVICES"] = ""
    os.environ["B12X_COMPILE_DISK_CACHE"] = "0"
    os.environ["B12X_COMPILE_MEMORY_CACHE"] = "0"
    sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "lib"))
    import _pinned_sparkinfer
    import multiprocessing
    from b12x._lib.compile_pool import _initialize_worker
    capability = (args.capability // 10, args.capability % 10)
    _initialize_worker(0, capability, "audio-offline", "audio-offline", 1,
                       101376, 101376, multiprocessing.Array("i", [0, 0]))
    from cutlass.cutlass_dsl import CuTeDSL
    CuTeDSL._get_dsl().envar.arch = f"sm_{args.capability}a"
    import torch
    import cutlass
    import cutlass.cute as cute
    from cutlass.cute.runtime import make_ptr
    from cuda.bindings import driver as cuda
    from b12x._lib.compiler import compile as compile_cute
    from b12x.norm.audio import AudioQuery, AudioSupport
    destination = args.output_dir
    destination.mkdir(parents=True, exist_ok=True)
    manifest_path = destination / "audio_support.json"
    manifest_path.unlink(missing_ok=True)
    pointers = [make_ptr(cutlass.Float32, 16, cute.AddressSpace.gmem, assumed_align=4) for _ in range(5)]
    pointers.append(make_ptr(cutlass.Int32, 16, cute.AddressSpace.gmem, assumed_align=4))
    for _, op, width, kernel, stride in OPERATIONS:
        AudioQuery(operation=op, width=width, kernel=kernel, stride=stride)
        stem = f"audio_{op}_{width}_{kernel}_{stride}"
        symbol = "cuteafd_" + stem
        program = compile_cute(AudioSupport(op, width, kernel, stride), *pointers,
            cutlass.Int32(1), cutlass.Int32(1), cutlass.Int32(0), cutlass.Float32(1e-5), cuda.CUstream(0))
        program.export_to_c(str(destination), stem, symbol)
        check_wrapper((destination / (stem + ".h")).read_text(), symbol)
        print(stem, flush=True)
    write_dispatcher(destination)
    table_hashes = write_tables(destination)
    files = {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(destination.iterdir())
        if p.is_file() and p.name not in {manifest_path.name, "audio_identity.h"}
        and p.suffix in {".o", ".h", ".cc"}}
    runtime = Path(__file__).resolve().parents[3] / "native/shared/cuda/audio_runtime.cu"
    abi_header = runtime.parent.parent / "include/cuteafd_audio.h"
    manifest = {"schema": 1, "numerics": "fp32_qualification_v1", "capability": list(capability),
        "sparkinfer_revision": _pinned_sparkinfer.REVISION,
        "source_tree_sha256": _pinned_sparkinfer.LOCK_DATA["source_tree_sha256"],
        "exporter_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "torch": torch.__version__, "cuda": torch.version.cuda,
        "nvcc": subprocess.check_output(["nvcc", "--version"], text=True).strip(),
        "host_compiler": subprocess.check_output(["c++", "--version"], text=True).splitlines()[0],
        "runtime_sha256": hashlib.sha256(runtime.read_bytes()).hexdigest(),
        "abi_header_sha256": hashlib.sha256(abi_header.read_bytes()).hexdigest(),
        "operations": OPERATIONS, "live_scalars": ["rows", "length", "offset", "parameter"],
        "rotary_capture_provenance": ROTARY_CAPTURE_PROVENANCE,
        "table_sha256": table_hashes, "artifacts": files}
    manifest["export_identity_sha256"] = write_identity(destination, manifest)
    manifest_path.write_text(json.dumps(manifest, indent=2) + "\n")
    if torch.cuda.is_initialized():
        raise RuntimeError("offline audio export initialized CUDA")


if __name__ == "__main__":
    main()
